def tr(language: str | None, key: str, **values: object) -> str:
    language = language if language in TEXTS else "ru"
    template = TEXTS[language].get(key, TEXTS["ru"].get(key, key))
    return template.format(**values) if values else template


def language_name(language: str) -> str:
    return {"ru": "Русский", "uz": "O‘zbekcha", "en": "English"}.get(language, "Русский")

